111	            ? new HeadlessSimulationView(rules)
112	            : new SimulatorView(depth, width, rules);
113	        for(PopulationRule rule : PRIMARY_POPULATION_RULES) {
114	            this.view.setColor(rule.getSpecies(), rule.getColor());
115	        }
